with RecentProducts as (select * from products where (product_name like 'O%' and brand in ('Initech', 'Umbrella', 'Acme')) or product_name like 'N%'), products_stats as (select year(launch_date) as launch_year, count(distinct price) as unique_categorys, max(stock_qty) - min(stock_qty) as stock_qty_range from RecentProducts group by year(launch_date)) select * from products_stats order by stock_qty_range desc
